"""Creates a GN include file for building weston from source."""

__author__ = "msisov@igalia.com (Dale Curtis)"

import datetime
import glob

COPYRIGHT = """# Copyright %d The Chromium Authors. All rights reserved.
# Use of this source code is governed by a BSD-style license that can be
# found in the LICENSE file.

# NOTE: this file is autogenerated by weston/generate_sources.py - DO NOT EDIT.

""" % (
    datetime.datetime.now().year)

# .c files which don't need -DBIT_DEPTH specified for each compilation.
#DAV1D_ENTRY_POINT_SOURCES = [
#    "libdav1d/src/lib.c",
#    "libdav1d/src/thread_task.c",
#    "libdav1d/src/thread_task.h",
#]

# .c files which are included by other .c files and shouldn't be listed.
#DAV1D_C_FILE_INCLUDES = ["libdav1d/src/itx_1d.c"]


def WriteArray(fd, var_name, array, filter_list=[], last_entry=False):
  if len(array) == 0:
    fd.write("var_name = []\n")
    return

  fd.write("%s = [\n" % var_name)
  for item in sorted(array):
    if item not in filter_list:
      fd.write("  \"%s\",\n" % item)
  fd.write("]\n")
  if not last_entry:
    fd.write("\n")


def WriteGn(fd):
  fd.write(COPYRIGHT)
  WriteArray(fd, "clients_sources", glob.glob("clients/*.[c|h]"))
  WriteArray(fd, "compositor_sources", glob.glob("compositor/*.[c|h]"))
  WriteArray(fd, "desktop_shell_sources",
      glob.glob("desktop-shell/*.[c|h]"))
  WriteArray(fd, "fullscreen_shell_sources",
      glob.glob("fullscreen-shell/*.c"))
  WriteArray(fd, "libweston_wayland_sources",
      glob.glob("libweston/backend-wayland/*.c") +
      glob.glob("libweston/*.[c|h]") +
      glob.glob("libweston/renderer-gl/*.[c|h]"))
  WriteArray(fd, "libweston_desktop_sources",
      glob.glob("libweston-desktop/*.[c|h]"))
  WriteArray(fd, "shared_sources",
      glob.glob("shared/*.[c|h]"))

#
#  WriteArray(fd, "desktop_shell_sources", glob.glob("src/desktop_shell/*.[c|h]"))
#  WriteArray(fd, "arm_template_sources", glob.glob("libdav1d/src/arm/*_tmpl.c"))
#
#  template_sources = glob.glob("libdav1d/src/*_tmpl.c")
#  WriteArray(fd, "template_sources", template_sources)
#
#  # Generate list of sources which need to be compiled multiple times with the
#  # correct -DBIT_DEPTH=8|10 option specified each time.
#  WriteArray(
#      fd, "c_sources", glob.glob("libdav1d/src/*.[c|h]"),
#      DAV1D_ENTRY_POINT_SOURCES + DAV1D_C_FILE_INCLUDES + template_sources)
#
#  WriteArray(
#      fd, "entry_point_sources", DAV1D_ENTRY_POINT_SOURCES, last_entry=True)


def main():
  with open("weston_generated.gni", "w") as fd:
    WriteGn(fd)


if __name__ == "__main__":
  main()

